    neutral: "text-card-foreground",
    destructive: `feedback-tone-destructive ${TONED}`,
    success: `feedback-tone-success ${TONED}`,
    warning: `feedback-tone-warning ${TONED}`,
    info: `feedback-tone-info ${TONED}`,
} as const;

