    tone?: keyof typeof TONE | null;
    class?: ClassValue;
    className?: ClassValue;
}

export function alertVariants(options: AlertVariants = {}): string {
    return joinClassValues(
        BASE,
        TONE[options.tone ?? "neutral"],
        options.class,
        options.className,
    );
}

