precision highp float;

in vec2 vUv;
out vec4 fragColor;

#define MAX_NUCLEI 8
#define BLUR_RINGS ${IMAGE_BLUR_RINGS}
#define BLUR_SECTORS ${IMAGE_BLUR_SECTORS}
const float PI = 3.141592653589793;

uniform float uTime;

