const AURORA_LABEL = "[Aurora]";

export const UNIFORM_NAMES = [
    "uTime",
    "uPalette",
    "uStopCount",
    "uNucleiCount",
    "uNucleiPos",
    "uNucleiRadius",
    "uNucleiPaletteBias",
    "uNucleiValueBias",
    "uNucleiDriftRadius",
    "uNucleiDriftPhase",
    "uNucleiElong",
    "uNucleiAngle",
    "uSoftmaxBeta",
    "uValueVariance",
    "uWarpAmount",
    "uWarpScale",
    "uWarpDrift",
    "uWarpMode",
    "uNoiseOctaves",
    "uMedium",
    "uHuePath",
    "uFlowPattern",
    "uFlowFocal",
    "uFlowAngle",
    "uFlowCurl",
    "uCursor",
    "uCursorStrength",
    "uCursorRadius",
    "uStrokeAmount",
    "uStrokeScale",
    "uStrokeAnisotropy",
    "uStrokeLayers",
    "uStrokeMode",
    // Stroke-orientation source (flow | tensor).
    "uStrokeOrient",
    // The movable impasto relight axis (cursor as light).
    "uLightDir",
    "uLightColor",
    "uWetEdge",
    "uGranulation",
    "uImpasto",
    "uBrokenColor",
    "uCanvasGrain",
    // Metal-medium knobs (uMedium==8/9).
    "uMetalPolish",
    "uMetalHeightScale",
    "uNucleiDrift",
    "uPaletteDrift",
    "uBreathDepth",
    "uBreathPeriod",
    "uSaturation",
    "uPaperGrain",
    "uAlpha",
    // Chroma-floor strength.
    "uVividness",
    // The image program's own uniform lane (the sampler + the
