export type UniformLocations = Record<UniformName, WebGLUniformLocation | null>;

export interface GlProgram {
    program: WebGLProgram;
    vs: WebGLShader;
    fs: WebGLShader;
    uniforms: UniformLocations;
    geometry: { vao: WebGLVertexArrayObject; buf: WebGLBuffer };
