  float modeLift = mix(1.18, 1.0, clamp(lab.x * 1.4, 0.0, 1.0));
  float Cmin = uVividness * VIVID_TARGET * modeLift;
  vec2 hueDir = (C > VIVID_EPS) ? lab.yz / C : VIVID_WARM_ANCHOR;
  lab.yz = hueDir * max(C, Cmin);
