const BUFFER_USAGE_UNIFORM = 0x40;
const BUFFER_USAGE_COPY_DST = 0x8;
const SHADER_STAGE_FRAGMENT = 0x2;

const PREMULTIPLIED_BLEND: GPUBlendState = {
    color: {
        srcFactor: "one",
        dstFactor: "one-minus-src-alpha",
        operation: "add",
