        trailRadLocs.push(gl.getUniformLocation(prog, `uTrailRadius[${i}]`));
    }

    // Per-palette-stop locations (uPalette[MAX_BLOB_STOPS]).
    const paletteLocs: (WebGLUniformLocation | null)[] = [];
