        prog,
        vs,
        fs,
        vao,
        buf,
        locs: {
            U,
            satPosLocs,
            satRadLocs,
            satOpLocs,
            satColorLocs,
            satColorAmtLocs,
            trailPosLocs,
            trailRadLocs,
