    settled: Readonly<Ref<boolean>>;
    /** Last quiescent frame actually drawn by either backend; `null` before settle. */
    settledFrame: Readonly<Ref<BlobSettledFrame | null>>;
    readonly rendererStatus: Readonly<Ref<RendererStatus>>;
}

