import { METABALL_SDF_GLSL } from "./sdf-body.glsl";
import {
    METABALL_EDGE_NOISE_PRE_GLSL,
    METABALL_EDGE_NOISE_POST_GLSL,
} from "./watercolor-edges.glsl";
import { METABALL_OKLCH_PERTURB_GLSL } from "./oklch-perturb.glsl";

