const MAX_SATS: i32 = 4;
const TRAIL_N: i32 = 15;
const MAX_BLOB_STOPS: i32 = 4;
const PI: f32 = 3.141592653589793;

// ── Uniforms (the typed-struct source-of-truth — see uniformBridgeWGPU.ts) ──
