        typeof window !== "undefined" &&
        /[?&](export|print|freeze)\b/.test(window.location.search);
    const isFrozen = computed(() =>
        rawFreeze === undefined ? urlFreeze() : rawFreeze === true || rawFreeze === "",
    );

