    let halo = (1.0 - smoothstep(0.0, haloR, dHead)) * glow;
    let core = (1.0 - smoothstep(coreR, coreR + aa, dHead)) * peak;
    let alpha = clamp(max(core, halo), 0.0, 1.0);
    return vec4<f32>(rgb * alpha, alpha);
  }
}
`;

