// WGSL primaries carry the same line for the same reason (aurora.wgsl.ts:49,
// metaball.wgsl.ts:53); this is that house idiom, not a local patch. The CLASS is gated
// by tests/components/fourier-field/wgsl-splice-contract.test.ts, which resolves every
// assembled module against the chunks it splices.
const PI: f32 = 3.141592653589793;

const TANGENT_EPS: f32 = 1e-4;
const SPEED_REF_HALFWIDTHS: f32 = 6.0;
// The trail's taper: the mark keeps this fraction of its width at the oldest tail.
const TAIL_TAPER: f32 = 0.55;

struct RenderUniforms {
  // r0: (centerX, centerY, scale, aspect)
  r0: vec4<f32>,
  // r1: (markHalf, inkOffsetStrokes, scaffoldFrac, edgeMargin)
  r1: vec4<f32>,
  // r2: (peakAlpha, glow, squash, trailFadeExp)
  r2: vec4<f32>,
  // r3: (trailFloor, hueSweep, ringStrokeModel, showMachine)
  r3: vec4<f32>,
  // ink: (linear rgb, rainbowChain)
  ink: vec4<f32>,
  // head: (linear rgb, _pad)
  head: vec4<f32>,
  // ints: (sampleCount, lutSize, chainCount, _pad)
  ints: vec4<i32>,
  // the CPU-resolved linear-sRGB ramp — the length is the TS constant, not a second copy
  lut: array<vec4<f32>, ${FOURIER_LUT_SIZE}>,
};

@group(0) @binding(0) var<uniform> u: RenderUniforms;
@group(0) @binding(1) var<storage, read> curveSamples: array<vec4<f32>>;
@group(0) @binding(2) var<storage, read> chainTips: array<vec4<f32>>;

${OETF_WGSL}
${OKLCH_MATRICES_WGSL}

// Read the CPU-resolved ramp. No colour-space conversion happens here — the LUT already
// carries the chroma floor and the gamut map.
fn sampleRamp(t: f32) -> vec3<f32> {
  let n = u.ints.y;
  let ft = clamp(t, 0.0, 1.0) * f32(n - 1);
  let i0 = i32(floor(ft));
  let i1 = min(i0 + 1, n - 1);
  return mix(u.lut[i0].rgb, u.lut[i1].rgb, ft - f32(i0));
}

// The chain's hue sweep, taken ONCE PER INSTANCE in the vertex stage: the ramp entry for
// this arm, rotated about the palette anchor by ±hueSweep. Anchored warm, the sweep is
// bounded by its own arithmetic — it cannot arrive anywhere the palette is not.
fn chainTint(seg: f32) -> vec3<f32> {
  let base = sampleRamp(seg * 0.6);
  if (u.ink.w < 0.5) { return base; }
  let lab = LMS_TO_OKLAB * cbrt3(LINEAR_SRGB_TO_LMS * base);
  let lch = oklabToOklch(lab);
  let swept = vec3<f32>(lch.x, lch.y, lch.z + mix(-u.r3.y, u.r3.y, clamp(seg, 0.0, 1.0)));
  return oklabToLinearSrgb(oklchToOklab(swept));
}

fn segDist(p: vec2<f32>, a: vec2<f32>, b: vec2<f32>) -> f32 {
  let pa = p - a;
  let ba = b - a;
  let h = clamp(dot(pa, ba) / max(dot(ba, ba), 1e-8), 0.0, 1.0);
  return length(pa - ba * h);
}

// The head's travel frame + its volume-preserving anisotropic metric.
struct HeadFrame { T: vec2<f32>, sHat: f32, };
fn headFrame(head: vec2<f32>, back: vec2<f32>, halfW: f32) -> HeadFrame {
  let d = head - back;
  let s = length(d);
  var out: HeadFrame;
  if (s <= TANGENT_EPS) {
    out.T = vec2<f32>(1.0, 0.0);
    out.sHat = 0.0;
    return out;
  }
  out.T = d / s;
  out.sHat = clamp(s / max(halfW * SPEED_REF_HALFWIDTHS, 1e-6), 0.0, 1.0);
  return out;
}

fn headAniso(p: vec2<f32>, head: vec2<f32>, fr: HeadFrame, k: f32) -> f32 {
  let g = 1.0 + k * fr.sHat;
  let n = vec2<f32>(-fr.T.y, fr.T.x);
  let rel = p - head;
  return length(vec2<f32>(dot(rel, fr.T) / g, dot(rel, n) * g));
}

fn quadCorner(vi: u32) -> vec2<f32> {
  var c = array<vec2<f32>, 6>(
    vec2<f32>(0.0, 0.0), vec2<f32>(1.0, 0.0), vec2<f32>(0.0, 1.0),
    vec2<f32>(0.0, 1.0), vec2<f32>(1.0, 0.0), vec2<f32>(1.0, 1.0),
  );
  return c[vi];
}

struct VSOut {
  @builtin(position) pos: vec4<f32>,
  @location(0) p: vec2<f32>,
  @location(1) a: vec2<f32>,
  @location(2) b: vec2<f32>,
  // (age, strokeHalf, drawRing)
  @location(3) seg: vec3<f32>,
  @location(4) @interpolate(flat) tint: vec3<f32>,
};

@vertex
fn vs_main(@builtin(vertex_index) vi: u32, @builtin(instance_index) inst: u32) -> VSOut {
  let corner = quadCorner(vi);
  let center = u.r0.xy;
  let scale = max(u.r0.z, 1e-6);
  let aspect = max(u.r0.w, 1e-4);
  let markHalf = u.r1.x;
  let margin = u.r1.w;

  var a = vec2<f32>(0.0);
  var b = vec2<f32>(0.0);
  var strokeHalf = markHalf;
  var age = 0.0;
  var drawRing = 0.0;
  var tint = vec3<f32>(0.0);
  var isCapsule = true;
  var ext = markHalf;

  if (LAYER == 0) {
    // CHAIN — the AABB around this arm's own orbit (radius = |b − a| = |c_k|).
    a = chainTips[inst].xy;
    b = chainTips[inst + 1u].xy;
    let radius = length(b - a);
    // THE RING LAW, asked of the live stage: a circle narrower than its own line is a blob.
    if (2.0 * radius >= u.r3.z) { drawRing = 1.0; }
    strokeHalf = markHalf * u.r1.z;
    tint = chainTint(f32(inst) / max(f32(u.ints.z) - 1.0, 1.0));
    ext = radius + strokeHalf * 2.0;
    isCapsule = false;
  } else if (LAYER == 1) {
    // TRAIL — the curve capsule, padded for the ink's own offset.
    a = curveSamples[inst].xy;
    b = curveSamples[inst + 1u].xy;
    age = max(curveSamples[inst].z, curveSamples[inst + 1u].z);
    tint = sampleRamp(1.0 - age);
    ext = markHalf * (1.0 + 2.0 * max(u.r1.y, 0.0));
    isCapsule = true;
  } else {
    // HEAD — centred on the newest curve sample; the AABB is the halo.
    a = curveSamples[0].xy;
    b = curveSamples[1].xy;
    tint = u.head.rgb;
    ext = markHalf * 5.0;
    isCapsule = false;
  }
  ext = ext + margin;

  var pos: vec2<f32>;
  if (isCapsule) {
    let d = b - a;
    let len = length(d);
    var dir = vec2<f32>(1.0, 0.0);
    if (len > 1e-6) { dir = d / len; }
    let perp = vec2<f32>(-dir.y, dir.x);
    pos = mix(a - dir * ext, b + dir * ext, corner.x) + perp * (corner.y * 2.0 - 1.0) * ext;
  } else {
    pos = a + (corner * 2.0 - vec2<f32>(1.0)) * ext;
  }

  var out: VSOut;
  out.pos = vec4<f32>((pos.x - center.x) * scale / aspect, (pos.y - center.y) * scale, 0.0, 1.0);
  out.p = pos;
  out.a = a;
  out.b = b;
  out.seg = vec3<f32>(age, strokeHalf, drawRing);
  out.tint = tint;
  return out;
}

@fragment
fn fs_main(in: VSOut) -> @location(0) vec4<f32> {
  let p = in.p;
  let aa = max(fwidth(p.x) + fwidth(p.y), 1e-5) * 0.75;
  let peak = u.r2.x;
  let glow = u.r2.y;
  let squash = u.r2.z;
  let fadeExp = u.r2.w;
  let trailFloor = u.r3.x;
  let markHalf = u.r1.x;
  let strokeHalf = in.seg.y;
  let age = in.seg.x;
  let a = in.a;
  let b = in.b;

  if (LAYER == 0) {
    // ── THE MACHINE — ring (conditionally), arm, joint dot; one scaffold rung ──
    let radius = length(b - a);
    var m = 0.0;
    if (in.seg.z > 0.5) {
      let dRing = abs(length(p - a) - radius);
      m = max(m, 1.0 - smoothstep(strokeHalf, strokeHalf + aa, dRing));
    }
    m = max(m, 1.0 - smoothstep(strokeHalf, strokeHalf + aa, segDist(p, a, b)));
    // The joint dot is the mark's own diameter — the machine's one solid rung.
    m = max(m, 1.0 - smoothstep(markHalf, markHalf + aa, length(p - a)));
    let alpha = clamp(m, 0.0, 1.0) * peak;
    let rgb = clamp(linearToSrgb(in.tint), vec3<f32>(0.0), vec3<f32>(1.0));
    return vec4<f32>(rgb * alpha, alpha);
  } else if (LAYER == 1) {
    // ── THE CURVE — ink under mark, composited at α1, then ONE envelope ──
    let taper = TAIL_TAPER + (1.0 - TAIL_TAPER) * age;
    let half = markHalf * taper;
    // The ink rides THIS segment's own tangent, opposite the travel: the head runs from
    // b toward a, so the ink lands behind at (b − a).
    var dir = vec2<f32>(1.0, 0.0);
    let d = b - a;
    let len = length(d);
    if (len > 1e-6) { dir = d / len; }
    let off = dir * (markHalf * 2.0 * u.r1.y);

    let aMark = 1.0 - smoothstep(half, half + aa, segDist(p, a, b));
    let aInk = 1.0 - smoothstep(half, half + aa, segDist(p, a + off, b + off));

    let markRgb = clamp(linearToSrgb(in.tint), vec3<f32>(0.0), vec3<f32>(1.0));
    let inkRgb = clamp(linearToSrgb(u.ink.rgb), vec3<f32>(0.0), vec3<f32>(1.0));

    // Mark OVER ink, both fully opaque where they cover — the pair, then the envelope.
    let aPair = aMark + aInk * (1.0 - aMark);
    let rgbPair = markRgb * aMark + inkRgb * aInk * (1.0 - aMark);
    let env = peak * max(pow(max(age, 0.0), fadeExp), trailFloor);
    return vec4<f32>(rgbPair * env, aPair * env);
  } else {
    // ── THE HEAD — palette-lifted core over its own halo. Light-led, never white. ──
    let fr = headFrame(a, b, markHalf);
    let dHead = headAniso(p, a, fr, squash);
    let coreR = markHalf * 1.5;
    let haloR = coreR * 3.0;
    let rgb = clamp(linearToSrgb(in.tint), vec3<f32>(0.0), vec3<f32>(1.0));
    let halo = (1.0 - smoothstep(0.0, haloR, dHead)) * glow;
    let core = (1.0 - smoothstep(coreR, coreR + aa, dHead)) * peak;
    let alpha = clamp(max(core, halo), 0.0, 1.0);
    return vec4<f32>(rgb * alpha, alpha);
  }
}
`;

src/components/fourier-field/renderer/wg.before:
// The WebGPU renderer — the ONLY renderer.
//
// Two passes per frame: the compute kernel writes the curve samples and the chain tips
// into storage buffers sized to THIS spectrum, then one render pass issues three instanced
// draws (chain → trail → head) that vertex-pull those buffers. There is no second engine,
// no parity claim to keep, and no ceiling: the buffers are rebuilt when the spectrum
// changes and are exactly as large as the mint's own output.
//
// WHY THERE IS NO WEBGL FALLBACK. A second renderer is a second paint law, and this
// component's whole claim is that what you see is the transform. Where WebGPU is absent
// the field declares the failure and paints nothing — a blank stage a reader can ask
// about, never a silent black rectangle or a lookalike drawn by a different machine.

import type {
    WebGPUCanvasFrame,
    BackingSize,
} from "../../../composables/glass/webgpu/useWebGPUCanvas";
import type { WebGLCanvasFrame } from "../../../composables/glass/webgl/useWebGLCanvas";
import type { OklchStop } from "../../../composables/color";
import { FOURIER_FIELD_COMPUTE_WGSL } from "./compute.wgsl";
import { FOURIER_FIELD_RENDER_WGSL } from "./render.wgsl";
import {
    FOURIER_CHAIN_HUE_SWEEP,
    FOURIER_CURVE_SAMPLES,
    FOURIER_DPR_CAP,
    FOURIER_SCAFFOLD_STROKE_FRAC,
    type FourierFieldConfig,
} from "../constants";
import {
    FOURIER_PHASOR_BYTES,
    computeFourierFit,
    createFourierComputeScratch,
    createFourierRenderScratch,
    packFourierComputeUniforms,
    packFourierRenderUniforms,
    packPhasorTable,
    resolveFourierRamp,
    strokeToModel,
    type FourierFit,
    type FourierRamp,
} from "./uniforms";
import type { MintedSpectrum } from "./mint";

const BUFFER_USAGE_UNIFORM = 0x40;
const BUFFER_USAGE_STORAGE = 0x80;
const BUFFER_USAGE_COPY_DST = 0x8;
const SHADER_STAGE_VERTEX = 0x1;
const SHADER_STAGE_FRAGMENT = 0x2;
const SHADER_STAGE_COMPUTE = 0x4;

const WORKGROUP_SIZE = 64;
/** The trail's fade shape and its floor — the oldest tail never disappears entirely. */
const TRAIL_FADE_EXP = 1.35;
const TRAIL_FLOOR = 0.34;
/** The paint's peak alpha before the intensity envelope multiplies it. */
const PEAK_ALPHA = 0.92;

/** The three layer ids the pipeline-overridable `LAYER` constant selects. */
const LAYER = { chain: 0, trail: 1, head: 2 } as const;

export interface FourierRendererDeps {
    canvas: HTMLCanvasElement;
    config: FourierFieldConfig;
    /** The minted spectrum — re-read each frame; identity change triggers the re-upload. */
    getSpectrum: () => MintedSpectrum;
    /** The resolved palette stops, re-read each frame so a live edit reaches the ramp. */
    getPalette: () => OklchStop[];
    /** The single loop parameter `head_t ∈ [0,1)`. */
    getHeadT: () => number;
    /** Demand-gate (the renderer's quiescence layer). */
    shouldContinue: () => boolean;
    /** The per-frame hook — the clock advances here, inside the substrate's own frame. */
    onFrame?: (timeSec: number) => void;
}

/** Build the fourier-field `setupWGPU(device, context, format)` callback. */
export function createFourierWGPUSetup(
    deps: FourierRendererDeps,
): (
    device: GPUDevice,
    context: GPUCanvasContext,
    format: GPUTextureFormat,
) => WebGPUCanvasFrame {
    const { canvas, config, getSpectrum, getPalette, getHeadT, shouldContinue, onFrame } =
        deps;

    return function setupWGPU(device, context, format) {
        const computeModule = device.createShaderModule({
            label: "[FourierField] compute.wgsl",
            code: FOURIER_FIELD_COMPUTE_WGSL,
        });
        const renderModule = device.createShaderModule({
            label: "[FourierField] render.wgsl",
            code: FOURIER_FIELD_RENDER_WGSL,
        });

        const computeUniform = device.createBuffer({
            label: "[FourierField] compute-uniforms",
            size: createFourierComputeScratch().buffer.byteLength,
            usage: BUFFER_USAGE_UNIFORM | BUFFER_USAGE_COPY_DST,
        });
        const renderUniform = device.createBuffer({
            label: "[FourierField] render-uniforms",
            size: createFourierRenderScratch().buffer.byteLength,
            usage: BUFFER_USAGE_UNIFORM | BUFFER_USAGE_COPY_DST,
        });

        const computeBGL = device.createBindGroupLayout({
            label: "[FourierField] compute-bgl",
            entries: [
                { binding: 0, visibility: SHADER_STAGE_COMPUTE, buffer: { type: "uniform" } },
                {
                    binding: 1,
                    visibility: SHADER_STAGE_COMPUTE,
                    buffer: { type: "read-only-storage" },
                },
                { binding: 2, visibility: SHADER_STAGE_COMPUTE, buffer: { type: "storage" } },
                { binding: 3, visibility: SHADER_STAGE_COMPUTE, buffer: { type: "storage" } },
            ],
        });
        const computePipeline = device.createComputePipeline({
            label: "[FourierField] compute-pipeline",
            layout: device.createPipelineLayout({ bindGroupLayouts: [computeBGL] }),
            compute: { module: computeModule, entryPoint: "cs_main" },
        });

        const renderBGL = device.createBindGroupLayout({
            label: "[FourierField] render-bgl",
            entries: [
                {
                    binding: 0,
                    visibility: SHADER_STAGE_VERTEX | SHADER_STAGE_FRAGMENT,
                    buffer: { type: "uniform" },
                },
                {
                    binding: 1,
                    visibility: SHADER_STAGE_VERTEX | SHADER_STAGE_FRAGMENT,
                    buffer: { type: "read-only-storage" },
                },
                {
                    binding: 2,
                    visibility: SHADER_STAGE_VERTEX | SHADER_STAGE_FRAGMENT,
                    buffer: { type: "read-only-storage" },
                },
            ],
        });
        const renderLayout = device.createPipelineLayout({ bindGroupLayouts: [renderBGL] });

        // THE ONE BLEND — premultiplied component-wise MAX, every layer, no exceptions.
        const MAX_BLEND: GPUBlendState = {
            color: { srcFactor: "one", dstFactor: "one", operation: "max" },
            alpha: { srcFactor: "one", dstFactor: "one", operation: "max" },
        };
        const makePipeline = (layer: number): GPURenderPipeline =>
            device.createRenderPipeline({
                label: `[FourierField] pipeline-L${layer}`,
                layout: renderLayout,
                vertex: {
                    module: renderModule,
                    entryPoint: "vs_main",
                    constants: { LAYER: layer },
                },
                fragment: {
                    module: renderModule,
                    entryPoint: "fs_main",
                    constants: { LAYER: layer },
                    targets: [{ format, blend: MAX_BLEND }],
                },
                primitive: { topology: "triangle-list" },
            });
        const pipelines = {
            chain: makePipeline(LAYER.chain),
            trail: makePipeline(LAYER.trail),
            head: makePipeline(LAYER.head),
        };

        const computeScratch = createFourierComputeScratch();
        const renderScratch = createFourierRenderScratch();

        // ── Per-spectrum resources. Sized to the mint's own output, rebuilt on a swap. ──
        let minted: MintedSpectrum | null = null;
        let phasorBuffer: GPUBuffer | null = null;
        let curveBuffer: GPUBuffer | null = null;
        let chainBuffer: GPUBuffer | null = null;
        let computeBindGroup: GPUBindGroup | null = null;
        let renderBindGroup: GPUBindGroup | null = null;
        let fit: FourierFit = { centerX: 0, centerY: 0, scale: 1 };
        let fitMachine = config.showMachine;

        function releaseSpectrumBuffers(): void {
            phasorBuffer?.destroy();
            curveBuffer?.destroy();
            chainBuffer?.destroy();
            phasorBuffer = null;
            curveBuffer = null;
            chainBuffer = null;
        }

        function syncSpectrum(): void {
            const next = getSpectrum();
            const machineChanged = fitMachine !== config.showMachine;
            if (next === minted && !machineChanged) return;
            if (next !== minted) {
                minted = next;
                releaseSpectrumBuffers();
                const termCount = Math.max(next.terms.length, 1);
                phasorBuffer = device.createBuffer({
                    label: "[FourierField] phasors",
                    size: termCount * FOURIER_PHASOR_BYTES,
                    usage: BUFFER_USAGE_STORAGE | BUFFER_USAGE_COPY_DST,
                });
                curveBuffer = device.createBuffer({
                    label: "[FourierField] curve-samples",
                    size: FOURIER_CURVE_SAMPLES * 16,
                    usage: BUFFER_USAGE_STORAGE,
                });
                chainBuffer = device.createBuffer({
                    label: "[FourierField] chain-tips",
                    size: (termCount + 1) * 16,
                    usage: BUFFER_USAGE_STORAGE,
                });
                device.queue.writeBuffer(phasorBuffer, 0, packPhasorTable(next.terms));
                computeBindGroup = device.createBindGroup({
                    label: "[FourierField] compute-bg",
                    layout: computeBGL,
                    entries: [
                        { binding: 0, resource: { buffer: computeUniform } },
                        { binding: 1, resource: { buffer: phasorBuffer } },
                        { binding: 2, resource: { buffer: curveBuffer } },
                        { binding: 3, resource: { buffer: chainBuffer } },
                    ],
                });
                renderBindGroup = device.createBindGroup({
                    label: "[FourierField] render-bg",
                    layout: renderBGL,
                    entries: [
                        { binding: 0, resource: { buffer: renderUniform } },
                        { binding: 1, resource: { buffer: curveBuffer } },
                        { binding: 2, resource: { buffer: chainBuffer } },
                    ],
                });
            }
            fitMachine = config.showMachine;
            fit = computeFourierFit(minted!, fitMachine);
        }

        // ── The ramp, rebuilt only when the palette itself changes. ──
        let ramp: FourierRamp = resolveFourierRamp(getPalette());
        let rampKey = paletteKey(getPalette());
        function syncRamp(): void {
            const palette = getPalette();
            const key = paletteKey(palette);
            if (key === rampKey) return;
            rampKey = key;
            ramp = resolveFourierRamp(palette);
        }

        function resize(_s: BackingSize): void {}

        function frame(timeSec: number): void {
            onFrame?.(timeSec);
            syncSpectrum();
            syncRamp();
            if (!minted || !computeBindGroup || !renderBindGroup) return;

            const termCount = minted.terms.length;
            const harmonicN = Math.max(
                1,
                Math.min(Math.round(config.harmonics), termCount),
            );
            const chainCount = config.showMachine ? harmonicN : 0;
            const sampleCount = FOURIER_CURVE_SAMPLES;

            packFourierComputeUniforms(
                computeScratch,
                getHeadT(),
                config.trailArc,
                harmonicN,
                sampleCount,
                termCount,
            );
            device.queue.writeBuffer(computeUniform, 0, computeScratch.buffer);

            // The backing store is the leaf's; the CSS box derives from it and the local
            // DPR cap, never from clientWidth.
            const dpr = Math.min(
                typeof window === "undefined" ? 1 : window.devicePixelRatio || 1,
                FOURIER_DPR_CAP,
            );
            const cssMin = Math.min(canvas.width, canvas.height) / Math.max(dpr, 1);
            const aspect = canvas.width / Math.max(canvas.height, 1);
            const markHalfModel =
                strokeToModel(config.markStroke, fit.scale, cssMin) * 0.5;
            const ringStrokeModel = strokeToModel(config.markStroke, fit.scale, cssMin);
            // The AA feather's slop in MODEL units — a few CSS px so no bbox edge clips it.
            const edgeMargin =
                (6 * 2) / (Math.max(fit.scale, 1e-6) * Math.max(cssMin, 1));

            packFourierRenderUniforms(renderScratch, {
                fit,
                aspect,
                markHalfModel,
                inkOffsetStrokes: config.inkOffset,
                scaffoldFrac: FOURIER_SCAFFOLD_STROKE_FRAC,
                edgeMargin,
                peakAlpha: PEAK_ALPHA * config.intensity,
                glow: config.glow,
                squash: config.squash,
                trailFadeExp: TRAIL_FADE_EXP,
                trailFloor: TRAIL_FLOOR,
                hueSweep: FOURIER_CHAIN_HUE_SWEEP,
                ringStrokeModel,
                showMachine: config.showMachine,
                rainbowChain: config.rainbowChain,
                sampleCount,
                chainCount,
                ramp,
            });
            device.queue.writeBuffer(renderUniform, 0, renderScratch.buffer);

            const encoder = device.createCommandEncoder({ label: "[FourierField] frame" });
            const cpass = encoder.beginComputePass();
            cpass.setPipeline(computePipeline);
            cpass.setBindGroup(0, computeBindGroup);
            cpass.dispatchWorkgroups(Math.ceil(sampleCount / WORKGROUP_SIZE));
            cpass.end();

            const rpass = encoder.beginRenderPass({
                colorAttachments: [
                    {
                        view: context.getCurrentTexture().createView(),
                        clearValue: { r: 0, g: 0, b: 0, a: 0 },
                        loadOp: "clear",
                        storeOp: "store",
                    },
                ],
            });
            rpass.setBindGroup(0, renderBindGroup);
            if (chainCount > 0) {
                rpass.setPipeline(pipelines.chain);
                rpass.draw(6, chainCount, 0, 0);
            }
            rpass.setPipeline(pipelines.trail);
            rpass.draw(6, sampleCount - 1, 0, 0);
            rpass.setPipeline(pipelines.head);
