                    label: "[FourierField] compute-bg",
                    layout: computeBGL,
                    entries: [
                        { binding: 0, resource: { buffer: computeUniform } },
                        { binding: 1, resource: { buffer: phasorBuffer } },
                        { binding: 2, resource: { buffer: curveBuffer } },
                        { binding: 3, resource: { buffer: chainBuffer } },
