function baselineOf(rect: Frame, fs: number): number {
    const content = (EM_ASCENT + DESCENDER) * fs;
    const halfLeading = Math.max(0, (rect.height - content) / 2);
    return rect.y + halfLeading + EM_ASCENT * fs;
