/** `M x y L x y …` over an open polyline. */
export function serialize(points: Point[]): string {
    if (points.length === 0) return "";
    return points
        .map((p, i) => `${i === 0 ? "M" : "L"}${round(p.x)} ${round(p.y)}`)
