        resume: (reason) => {
            webgpu?.resume(reason);
            webgl2?.resume(reason);
        },
        wake: () => {
            webgpu?.wake();
            webgl2?.wake();
        },
        renderAt: (t) => {
            webgpu?.renderAt(t);
