        () => endpointRefs.map((endpoint) => endpoint.value),
        () => {
            if (!activeEl || !playing.value) return;
            observe(activeEl);
            refresh();
        },
        { flush: "post" },
    );

    onScopeDispose(() => {
        stopEndpointWatch();
        cancel();
    });

    return {
        play,
        cancel,
        clear,
        seat,
        offset,
        refresh,
        playing: readonly(playing),
        progress: readonly(progress),
        measurement: readonly(measurement),
    };
}

