        }
        currentGeometry = geometry;
        paint(el, frameAt(geometry, rawProgress));
    }

    function offset(x: number, y: number): void {
        const el = asElement(surface.value);
        if (!el) return;
        stopOwner();
        disconnectObserver();
        activeEl = el;
        releaseLock ??= lockSpatialTransition(el);
