        const container = containerRef.value;
        if (idx < 0) {
            singleSliderStyle.value = {
                ...singleSliderStyle.value,
                opacity: "0",
            };
            return;
        }
        if (!container || !buttonRefs.value[idx]) {
            singleSliderStyle.value = {
                ...singleSliderStyle.value,
                opacity: "0",
            };
            return;
        }
