                ? vertical.value
                    ? {
                          start: containerRect.top + (containerRef.value?.clientTop ?? 0),
                          end: containerRect.bottom,
                      }
                    : {
                          start: containerRect.left + (containerRef.value?.clientLeft ?? 0),
                          end: containerRect.right,
                      }
                : undefined;
