            el.style.setProperty(
                "--eyeglass-origin",
                `${eyeglassOriginPercent(organ.direction)}%`,
            );
            el.style.setProperty("--eyeglass-span", String(organ.span));
            el.style.setProperty("--eyeglass-swell", String(eyeglassSwell(frac)));
