    watch(
        () => toValue(scrollSource),
        (source) => attach(source),
        { flush: "post" },
    );
    const stopReducedMotionWatch = watch(reduced, recalculate, { flush: "sync" });

    onBeforeUnmount(() => {
        reader?.stop();
        reader = null;
        stopReducedMotionWatch();
    });

    return { progress, direction, velocity, recalculate };
}

